## Code Example

```javascript
// Example gating logic for latency-adaptive routing
function route(payload, limitMs) {
  const t0 = performance.now();
  const score = computeScore(payload);
  const dt = performance.now() - t0;
  if (dt > limitMs) return 'fallback';
  return score;
}
